SearchResult kmp(std::string_view source, std::string_view target) {
    const auto begin = Clock::now();
    size_t comparison_count = 0;

    if (target.empty()) {
        return make_result(
            empty_target_matches(source.size()),
            comparison_count,
            begin
        );
    }

    std::vector<size_t> matches;

    if (target.size() > source.size()) {
        return make_result(std::move(matches), comparison_count, begin);
    }

    // prefix[i]：target[0...i] 中，最长相同真前缀与后缀的长度
    std::vector<size_t> prefix(target.size(), 0);

    for (size_t index = 1, matched = 0; index < target.size();) {
        ++comparison_count;

        if (target[index] == target[matched]) {
            prefix[index] = matched + 1;
            ++index;
            ++matched;
        } else if (matched > 0) {
            matched = prefix[matched - 1];
        } else {
            prefix[index] = 0;
            ++index;
        }
    }

    // 在 source 中进行匹配
    for (size_t index = 0, matched = 0; index < source.size();) {
        ++comparison_count;

        if (source[index] == target[matched]) {
            ++index;
            ++matched;

            if (matched == target.size()) {
                matches.push_back(index - target.size());

                // 保留可能的重叠匹配
                matched = prefix[matched - 1];
            }
        } else if (matched > 0) {
            matched = prefix[matched - 1];
        } else {
            ++index;
        }
    }

    return make_result(std::move(matches), comparison_count, begin);
}  

